def xargs(
        cmd: tuple[str, ...],
        varargs: Sequence[str],
        *,
        color: bool = False,
        target_concurrency: int = 1,
        _max_length: int = _get_platform_max_length(),
        **kwargs: Any,
) -> tuple[int, bytes]:
    """A simplified implementation of xargs.

    color: Make a pty if on a platform that supports it
    target_concurrency: Target number of partitions to run concurrently
    """
    import subprocess
    import os
    from itertools import islice

    if target_concurrency < 1:
        raise ValueError("target_concurrency must be at least 1")

    if _max_length <= 0:
        raise ValueError("_max_length must be positive")

    def chunks(lst, n):
        """Yield successive n-sized chunks from lst."""
        for i in range(0, len(lst), n):
            yield lst[i:i + n]

    def create_command(chunk):
        return cmd + tuple(chunk)

    results = []
    processes = []

    try:
        for chunk in chunks(varargs, (_max_length - len(' '.join(cmd))) // max(1, len(varargs[0]) + 1) if varargs else 1):
            full_cmd = create_command(chunk)
            if color and os.name != 'nt' and hasattr(os, 'posix_spawn'):
                # Create a pseudo-terminal
                master_fd, slave_fd = os.openpty()
                process = subprocess.Popen(full_cmd, stdin=subprocess.PIPE, stdout=slave_fd, stderr=subprocess.STDOUT, **kwargs)
                os.close(slave_fd)
            else:
                process = subprocess.Popen(full_cmd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, **kwargs)
            processes.append((process, master_fd if color else process.stdout))

        for process, output_stream in processes:
            output, _ = process.communicate()
            results.append((process.returncode, output if output_stream is process.stdout else os.read(output_stream, 1024*1024)))
            if color and isinstance(output_stream, int):
                os.close(output_stream)

        final_result = (0, b'')
        for code, output in results:
            final_result = (final_result[0] or code, final_result[1] + output)

        return final_result

    except Exception as e:
        for process, output_stream in processes:
            if process.poll() is None:
                process.terminate()
            if isinstance(output_stream, int):
                os.close(output_stream)
        raise e

def xargs(
        cmd: tuple[str, ...],
        varargs: Sequence[str],
        *,
        color: bool = False,
        target_concurrency: int = 1,
        _max_length: int = _get_platform_max_length(),
        **kwargs: Any,
) -> tuple[int, bytes]:
    """A simplified implementation of xargs.

    color: Make a pty if on a platform that supports it
    target_concurrency: Target number of partitions to run concurrently
    """
    import subprocess
    import os
    from itertools import islice

    if target_concurrency < 1:
        raise ValueError("target_concurrency must be at least 1")

    def chunks(iterable, n):
        it = iter(iterable)
        while True:
            chunk = list(islice(it, n))
            if not chunk:
                break
            yield chunk

    processes = []
    results = []
