def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    try:
        seen = set()
        minimized = []
        for cls in classes:
            if cls not in seen:
                seen.add(cls)
                minimized.append(cls)
                for subclass in cls.__subclasses__():
                    seen.add(subclass)
        return minimized
    except Exception as e:
        raise ValueError(f"An error occurred while minimizing base classes: {e}")

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    try:
        seen = set()
        result = []
        for cls in classes:
            if cls not in seen:
                seen.add(cls)
                for parent in cls.__bases__:
                    if parent in seen:
                        seen.remove(parent)
                result.append(cls)
        return [cls for cls in classes if cls in seen]
    except Exception as e:
        raise ValueError(f"Error reducing base classes: {e}")

