def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    if len(bins) + 1 != len(edges):
        raise ValueError("The number of bins must be one less than the number of edges.")

    try:
        integral_value = sum(bin_val * (edge2 - edge1) for bin_val, edge1, edge2 in zip(bins, edges, edges[1:]))
    except TypeError:
        raise TypeError("All elements in bins and edges must be numbers.")

    return integral_value

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    try:
        if len(bins) != len(edges) - 1:
            raise ValueError("The number of bins must be one less than the number of edges.")

        integral_value = 0.0
        for i in range(len(bins)):
            width = edges[i + 1] - edges[i]
            integral_value += bins[i] * width

        return integral_value

    except TypeError:
        raise TypeError("Both bins and edges must be iterable with numerical values.")
    except Exception as e:
        raise Exception(f"An error occurred: {str(e)}")

