                out_params = params
            elif self.SQLParams.out_style == 'format':
                sql = sql.replace('%s', lambda m, c=iter(range(1, len(params) + 1)): ':' + str(next(c)))
                out_params = {i + 1: v for i, v in enumerate(params)}
        elif self.SQLParams.in_style in ('named', 'pyformat'):
            if not isinstance(params, Mapping):
                raise ValueError("params must be a Mapping for this in-style")
