            if self.SQLParams.out_style == 'named':
                sql = sql.replace('%(', ':')
                out_params = params
            elif self.SQLParams.out_style == 'pyformat':
                sql = sql.replace('%(', '{')
                sql = sql.replace(')', '}')
                out_params = params
        else:
            raise ValueError("Unsupported in-style parameter")
        return sql, out_params
    except Exception as e:
        raise ValueError(f"Error formatting SQL: {e}")

