                formatted_sql = formatted_sql.replace(f"%s", f"%({placeholder})s", 1)
            return formatted_sql, list(params)
        else:
            raise ValueError(f"Unsupported parameter style: {self.SQLParams.in_style}")
    except Exception as e:
        raise ValueError(f"Error formatting SQL: {e}")

