def _extract_number_and_supplment_from_issue_element(issue):
    """
    Extrai do conteúdo de <issue>xxxx</issue>, os valores number e suppl.
    Valores possíveis
    5 (suppl), 5 Suppl, 5 Suppl 1, 5 spe, 5 suppl, 5 suppl 1, 5 suppl. 1,
    25 Suppl 1, 2-5 suppl 1, 2spe, Spe, Supl. 1, Suppl, Suppl 12,
    s2, spe, spe 1, spe pr, spe2, spe.2, spepr, supp 1, supp5 1, suppl,
    suppl 1, suppl 5 pr, suppl 12, suppl 1-2, suppl. 1
    """
    import re

    try:
        issue = issue.strip()
        number = None
        suppl = None

        # Regular expression to match the patterns
        pattern = re.compile(
            r'^(?P<number>\d+(?:-\d+)?)(?:\s*(?P<suppl_text>suppl|supp|spe|spe\.\d+|spe\d+|spe\.\d+|s\d+|supp\d+|suppl\d+|suppl\.\d+|suppl\s\d+|\s\d+(?:-\d+)?|pr|\.?pr)?)?',
            re.IGNORECASE
        )

        match = pattern.match(issue)
        if match:
            number = match.group('number')
            suppl_text = match.group('suppl_text')
            if suppl_text:
                suppl = re.sub(r'\s+', ' ', suppl_text.strip()).lower()
                if suppl in ['supp', 'suppl', 'spe', 's', 'suppl.', 'spe.', 'supp.']:
                    suppl = 'suppl'
                elif suppl in ['pr', 'spepr', 'supplpr']:
                    suppl = 'suppl pr'
                elif suppl.startswith('s'):
                    suppl = 'suppl' + suppl[1:]
                elif suppl.startswith('spe'):
                    suppl = 'suppl' + suppl[3:]
                elif suppl.startswith('supp'):
                    suppl = 'suppl' + suppl[4:]
                elif suppl.startswith('suppl'):
                    suppl = suppl
                else:
                    suppl = None

        return number, suppl
    except Exception as e:
        print(f"An error occurred: {e}")
        return None, None

