        return expr

    stack = deque(args)
    result = []

    while stack:
        expr = stack.popleft()
        if isinstance(expr, tuple) and len(expr) == 3:
            op, left, right = expr
            if isinstance(left, tuple):
                stack.appendleft(right)
                stack.appendleft(left)
            elif isinstance(right, tuple):
                stack.appendleft(left)
                stack.appendleft(right)
            else:
                result.append(apply_absorption(expr))
        else:
            result.append(expr)

    return result

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    try:
        new_args = []
        for expr in args:
            if isinstance(expr, tuple) and len(expr) == 3:
                op, a, b = expr
                if op == '&':
                    if b == (a, '|'):
                        new_args.append(a)
                    elif isinstance(b, tuple) and b[0] == '|' and b[1] == (~a):
                        new_args.append((op, a, b[2]))
                    else:
                        new_args.append(expr)
                elif op == '|':
                    if b == (a, '&'):
                        new_args.append(a)
                    elif isinstance(b, tuple) and b[0] == '&' and b[1] == (~a):
                        new_args.append((op, a, b[2]))
                    else:
                        new_args.append(expr)
                else:
                    new_args.append(expr)
            else:
                new_args.append(expr)
        return new_args
    except Exception as e:
        raise ValueError(f"Error processing expression: {e}")

