def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    if not isinstance(version_dirs, list):
        raise ValueError("version_dirs must be a list of version directory names.")

    root_inventory = {}
    try:
        with open(os.path.join(self.root_directory, 'inventory.txt'), 'r') as f:
            for line in f:
                digest, path = line.strip().split(' ', 1)
                root_inventory[path] = digest
    except FileNotFoundError:
        raise FileNotFoundError("Root inventory file not found.")
    except Exception as e:
        raise Exception(f"Error reading root inventory file: {e}")

    for version_dir in version_dirs:
        version_path = os.path.join(self.root_directory, version_dir)
        version_inventory_path = os.path.join(version_path, 'inventory.txt')
        if not os.path.exists(version_inventory_path):
            raise FileNotFoundError(f"Inventory file not found for version: {version_dir}")

        version_inventory = {}
        try:
            with open(version_inventory_path, 'r') as f:
                for line in f:
                    digest, path = line.strip().split(' ', 1)
                    version_inventory[path] = digest
        except Exception as e:
            raise Exception(f"Error reading inventory file for version {version_dir}: {e}")

        # Check if each entry in the version inventory is in the root inventory
        for path, digest in version_inventory.items():
            if path not in root_inventory:
                raise KeyError(f"Path {path} in version {version_dir} inventory not found in root inventory.")
            if root_inventory[path] != digest:
                raise ValueError(f"Digest mismatch for {path} in version {version_dir} inventory.")

        # Add any unique digests from this version to the root_inventory for future checks
        for path, digest in version_inventory.items():
            if path not in root_inventory or root_inventory[path] != digest:
                root_inventory[path] = digest

