def parser_flags(parser):
    '''Given an argparse.ArgumentParser instance, return its argument flags in a space-separated string.'''
    try:
        flags = [action.option_strings for action in parser._actions]
        all_flags = [flag for sublist in flags for flag in sublist]
        return ' '.join(all_flags)
    except Exception as e:
        raise ValueError(f"Error retrieving parser flags: {e}")

