    try:
        actions = parser._actions
        flags = [a.option_strings for a in actions if a.option_strings]
        flat_flags = [flag for sublist in flags for flag in sublist]
        return ' '.join(flat_flags)
    except AttributeError:
        raise ValueError("Provided object is not an instance of argparse.ArgumentParser")

