def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    size = size.upper()
    if size.isdigit():
        return int(size)
    try:
        value, unit = size[:-1], size[-1]
        value = int(value)
        if unit == 'K':
            return value * 1000
        elif unit == 'M':
            return value * 1000**2
        elif unit == 'G':
            return value * 1000**3
        elif unit == 'T':
            return value * 1000**4
        else:
            raise ValueError(f"Unknown unit: {unit}")
    except Exception as e:
        raise ValueError(f"Invalid size format: {size}") from e

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::
            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    size = size.strip()
    units = {'K': 1000, 'M': 1000**2, 'G': 1000**3, 'T': 1000**4, 'P': 1000**5}
    if size[-1] in units:
        number, unit = size[:-1], size[-1]
        return int(float(number) * units[unit])
    else:
        return int(size)

