def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import re
    import sys

    if platform == 'this':
        platform = 1 if sys.platform != 'win32' else 0

    if platform == 1:  # POSIX
        # Based on a simplified POSIX shlex behavior
        return re.findall(r"""(['"])(?:(?=(\\?))\2.)*?\1|\S+""", s)

    elif platform == 0:  # Windows/CMD
        # Based on a simplified CMD behavior
        return re.findall(r"""(['"])(?:(?=(\\?))\2.)*?\1|[^ \t'"]+""", s)

    else:
        raise ValueError("Unsupported platform value")

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import re
    import os

    if platform == 'this':
        platform = 1 if os.name == 'posix' else 0

    if platform == 1:  # POSIX
        pattern = re.compile(r'''(['"])([^"\\]*(?:\\.[^"\\]*)*)\1|([^ \t\n]+)''')
    elif platform == 0:  # Windows/CMD
        pattern = re.compile(r'''(["'])([^"\\]*(?:\\.[^"\\]*)*)\1|([^ \t\n]+)''')
    else:
        raise ValueError("Unsupported platform value")

    result = []
    for match in pattern.finditer(s):
        if match.group(1):
            result.append(match.group(2).replace('\\"', '"').replace('\\\\', '\\'))
        else:
            result.append(match.group(3))

    return result

