def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    import subprocess
    from pathlib import Path

    if isinstance(tmp_path, str):
        tmp_path = Path(tmp_path)

    try:
        # Create a temporary directory within the specified tmp_path
        repo_dir = tmp_path / Path(archive_path).stem
        repo_dir.mkdir(parents=True, exist_ok=True)

        # Determine the decompression command based on the archive type
        if archive_path.endswith('.tar.gz') or archive_path.endswith('.tgz'):
            command = ['tar', '-xzf', archive_path, '-C', str(repo_dir)]
        elif archive_path.endswith('.zip'):
            command = ['unzip', archive_path, '-d', str(repo_dir)]
        else:
            raise ValueError("Unsupported archive format")

        # Execute the decompression command
        subprocess.run(command, check=True)

        # If a specific filename is provided, construct the file URL
        if filename:
            file_path = repo_dir / filename
            if not file_path.exists():
                raise FileNotFoundError(f"File {filename} not found in the archive")
            return file_path.as_uri()

        # Return the repository directory URL
        return repo_dir.as_uri()

    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Failed to decompress archive: {e}")
    except Exception as e:
        raise Exception(f"An error occurred: {e}")

