def addignored(ignored):
    ''' Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.'''
    try:
        completed_process = subprocess.run(['git', 'status', '--ignored', '--porcelain'], check=True, stdout=subprocess.PIPE, text=True)
        output = completed_process.stdout.split('\n')
        ignored_files = [line.split()[1] for line in output if line.startswith('!!')]
        ignored_files.sort()
        return ', '.join(ignored_files)
    except subprocess.CalledProcessError as e:
        print(f"Error running git command: {e}")
        return ''

