    unit = unit.rstrip('s')  # Remove plural 's' if present
    unit_to_timedelta = {
        'second': {'seconds': value},
        'minute': {'minutes': value},
        'hour': {'hours': value},
        'day': {'days': value},
        'week': {'weeks': value},
        'month': {'days': value * 30},  # Approximation
        'year': {'days': value * 365}   # Approximation
    }

    if unit in unit_to_timedelta:
        return datetime.timedelta(**unit_to_timedelta[unit])
    else:
        raise ValueError(f"Unknown time unit: {unit}")

