def oneline(script, separator=" && "):
    """
    converts a script to one line command.
    This is useful to run a single ssh command and pass a one line script.

    :param script: str - The script to be converted.
    :param separator: str - The separator to use between lines. Defaults to " && ".
    :return: str - The one-liner command.
    """
    try:
        lines = script.splitlines()
        return separator.join(line.strip() for line in lines if line.strip())
    except Exception as e:
        raise ValueError(f"Error converting script to one-liner: {str(e)}")

def oneline(script, separator=" && "):
    """
    converts a script to one line command.
    This is useful to run a single ssh command and pass a one line script.

    :param script:
    :param separator: The separator to use between commands
    :return: A single line command
    """
    try:
        # Ensure the script is a list of strings
        if not isinstance(script, list):
            raise ValueError("Script must be a list of command strings")

        # Join the script into a single line command
        return separator.join(script)
    except Exception as e:
        raise ValueError(f"Error converting script to one line: {e}")

