def _resolve_string(matcher):
    '''
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    '''
    try:
        name, default = matcher
    except ValueError:
        name = matcher
        default = None

    value = os.getenv(name)
    if value is not None:
        return value
    elif default is not None:
        return default
    else:
        raise ValueError(f"Environment variable '{name}' is not defined and no default value was provided.")

def _resolve_string(matcher):
    '''
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    '''
    try:
        name, default = matcher.split('=', 1)
    except ValueError:
        name, default = matcher, None

    value = os.getenv(name.strip())
    if value is None:
        if default is None:
            raise ValueError(f"Environment variable '{name}' is not set and no default value is provided.")
        value = default.strip()

    return value

