                    if section in config:
                        config[section].update(settings)
            config_dict[filename] = {section: dict(config.items(section)) for section in config.sections()}
        except (FileNotFoundError, configparser.Error) as e:
            record = logging.LogRecord('config_loader', logging.ERROR, filename, 0, str(e), None, None)
            log_records.append(record)

