def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import logging
    import json
    import os
    import configparser

    def parse_config(filename):
        try:
            if filename.endswith('.json'):
                with open(filename, 'r') as f:
                    config = json.load(f)
            else:
                config = {}
                parser = configparser.ConfigParser()
                parser.read(filename)
                for section in parser.sections():
                    config[section] = {k: v for k, v in parser.items(section)}
            if resolve_env:
                config = {k: os.path.expandvars(v) for k, v in config.items()}
            return config
        except Exception as e:
            logger = logging.getLogger()
            return logger.makeRecord('ERROR', logging.ERROR, filename, 0, str(e), None, None)

    if overrides is None:
        overrides = {}

    configs = {}
    errors = []

    for filename in config_filenames:
        result = parse_config(filename)
        if isinstance(result, logging.LogRecord):
            errors.append(result)
        else:
            configs[filename] = result

    if overrides:
        for key, value in overrides.items():
            if key in configs:
                configs[key].update(value)
            else:
                configs[key] = value

    return configs, errors

