def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    from xml.etree import ElementTree
    from xml.etree.ElementTree import ParseError

    try:
        # Try parsing as JSON
        return json.loads(document)
    except json.JSONDecodeError:
        # If JSON parsing fails, try parsing as XML (XRD)
        try:
            root = ElementTree.fromstring(document)
            # Extract relevant information from XML
            # This is a simplified example; actual parsing logic may vary
            template = {
                'subject': '',
                'aliases': [],
                'links': []
            }
            subject = root.find('{http://docs.oasis-open.org/ns/xri/xrd-1.0}Subject')
            if subject is not None:
                template['subject'] = subject.text

            for alias in root.findall('{http://docs.oasis-open.org/ns/xri/xrd-1.0}Alias'):
                template['aliases'].append(alias.text)

            for link in root.findall('{http://docs.oasis-open.org/ns/xri/xrd-1.0}Link'):
                link_template = {
                    'rel': link.get('rel'),
                    'href': link.get('href'),
                    'type': link.get('type')
                }
                template['links'].append(link_template)

            return template
        except ParseError:
            raise ValueError("The provided document is neither valid JSON nor valid XRD XML.")

